+static bool isClockPin(const sta::Pin* pin, sta::dbNetwork* network)
+{
+  sta::LibertyPort* lp = network->libertyPort(pin);
+  if (!lp) {
+    return false;
+  }
+  return lp->isClock() || lp->isRegClk() || lp->isClockGateClock();
